package org.smartbook.service;

import lombok.AllArgsConstructor;
import lombok.Data;
import org.smartbook.model.Role;
import org.smartbook.model.User;
import org.smartbook.repository.RoleRepository;
import org.smartbook.repository.UserRepository;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;

@Service
@AllArgsConstructor
@Transactional
public class AuthenticationService {

    private final UserRepository userRepository;
    private final RoleRepository roleRepository;
    private final JwtService jwtService;
    private final PasswordEncoder passwordEncoder;

    public AuthenticationResponse register(RegisterRequest request) {
        if (userRepository.existsByEmail(request.getEmail())) {
            throw new RuntimeException("El email ya está registrado: " + request.getEmail());
        }

        Role role = roleRepository.findByNombre("USUARIO")
                .orElseGet(() -> {
                    Role newRole = new Role();
                    newRole.setNombre("USUARIO");
                    return roleRepository.save(newRole);
                });

        User user = new User();
        user.setNombre(request.getNombre());
        user.setApellido(request.getApellido());
        user.setEmail(request.getEmail());
        user.setPassword(passwordEncoder.encode(request.getPassword()));
        user.setRole(role);
        user.setCreatedAt(LocalDateTime.now());

        User savedUser = userRepository.save(user);
        String token = jwtService.generateToken(savedUser.getEmail());

        return new AuthenticationResponse(token, "Usuario registrado exitosamente");
    }

    public AuthenticationResponse authenticate(LoginRequest request) {
        User user = userRepository.findByEmail(request.getEmail())
                .orElseThrow(() -> new RuntimeException("Usuario no encontrado con email: " + request.getEmail()));

        if (!passwordEncoder.matches(request.getPassword(), user.getPassword())) {
            throw new RuntimeException("Contraseña incorrecta");
        }

        String token = jwtService.generateToken(user.getEmail());
        return new AuthenticationResponse(token, "Autenticación exitosa");
    }

    @Data
    public static class LoginRequest {
        private String email;
        private String password;
    }

    @Data
    public static class RegisterRequest {
        private String nombre;
        private String apellido;
        private String email;
        private String password;
    }

    @Data
    @AllArgsConstructor
    public static class AuthenticationResponse {
        private String token;
        private String message;
    }
}

package org.smartbook.service;

import lombok.AllArgsConstructor;
import org.smartbook.dto.CursoDTO;
import org.smartbook.model.Curso;
import org.smartbook.repository.CursoRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.stream.Collectors;

@Service
@AllArgsConstructor
@Transactional
public class CursoService {

    private final CursoRepository cursoRepository;

    public CursoDTO createCurso(CursoDTO cursoDTO) {
        Curso curso = new Curso();
        curso.setNombre(cursoDTO.getNombre());
        curso.setNivel(cursoDTO.getNivel());
        curso.setAnio(cursoDTO.getAnio());

        Curso savedCurso = cursoRepository.save(curso);
        return convertToDTO(savedCurso);
    }

    @Transactional(readOnly = true)
    public CursoDTO getCursoById(Integer id) {
        Curso curso = cursoRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Curso no encontrado con ID: " + id));
        return convertToDTO(curso);
    }

    @Transactional(readOnly = true)
    public List<CursoDTO> getAllCursos() {
        return cursoRepository.findAll()
                .stream()
                .map(this::convertToDTO)
                .collect(Collectors.toList());
    }

    @Transactional(readOnly = true)
    public List<CursoDTO> getCursosByAnio(Integer anio) {
        return cursoRepository.findByAnio(anio)
                .stream()
                .map(this::convertToDTO)
                .collect(Collectors.toList());
    }

    public CursoDTO updateCurso(Integer id, CursoDTO cursoDTO) {
        Curso curso = cursoRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Curso no encontrado con ID: " + id));

        curso.setNombre(cursoDTO.getNombre());
        curso.setNivel(cursoDTO.getNivel());
        curso.setAnio(cursoDTO.getAnio());

        Curso updatedCurso = cursoRepository.save(curso);
        return convertToDTO(updatedCurso);
    }

    public void deleteCurso(Integer id) {
        if (!cursoRepository.existsById(id)) {
            throw new RuntimeException("Curso no encontrado con ID: " + id);
        }
        cursoRepository.deleteById(id);
    }

    private CursoDTO convertToDTO(Curso curso) {
        return new CursoDTO(curso.getId(), curso.getNombre(), curso.getNivel(), curso.getAnio());
    }
}

package org.smartbook.service;

import lombok.AllArgsConstructor;
import org.smartbook.dto.EstudianteDTO;
import org.smartbook.model.Curso;
import org.smartbook.model.Estudiante;
import org.smartbook.model.Role;
import org.smartbook.repository.CursoRepository;
import org.smartbook.repository.EstudianteRepository;
import org.smartbook.repository.RoleRepository;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.List;
import java.util.stream.Collectors;

@Service
@AllArgsConstructor
@Transactional
public class EstudianteService {

    private final EstudianteRepository estudianteRepository;
    private final RoleRepository roleRepository;
    private final CursoRepository cursoRepository;
    private final PasswordEncoder passwordEncoder;

    public EstudianteDTO createEstudiante(EstudianteDTO estudianteDTO) {
        if (estudianteRepository.existsByMatricula(estudianteDTO.getMatricula())) {
            throw new RuntimeException("La matrícula ya existe: " + estudianteDTO.getMatricula());
        }

        Role role = roleRepository.findById(estudianteDTO.getRolId())
                .orElseThrow(() -> new RuntimeException("Rol no encontrado con ID: " + estudianteDTO.getRolId()));

        Curso curso = cursoRepository.findById(estudianteDTO.getCursoId())
                .orElseThrow(() -> new RuntimeException("Curso no encontrado con ID: " + estudianteDTO.getCursoId()));

        Estudiante estudiante = new Estudiante();
        estudiante.setNombre(estudianteDTO.getNombre());
        estudiante.setApellido(estudianteDTO.getApellido());
        estudiante.setEmail(estudianteDTO.getEmail());
        estudiante.setPassword(passwordEncoder.encode(estudianteDTO.getPassword()));
        estudiante.setRole(role);
        estudiante.setCurso(curso);
        estudiante.setMatricula(estudianteDTO.getMatricula());
        estudiante.setCreatedAt(LocalDateTime.now());

        Estudiante savedEstudiante = estudianteRepository.save(estudiante);
        return convertToDTO(savedEstudiante);
    }

    @Transactional(readOnly = true)
    public EstudianteDTO getEstudianteById(Integer id) {
        Estudiante estudiante = estudianteRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Estudiante no encontrado con ID: " + id));
        return convertToDTO(estudiante);
    }

    @Transactional(readOnly = true)
    public EstudianteDTO getEstudianteByMatricula(String matricula) {
        Estudiante estudiante = estudianteRepository.findByMatricula(matricula)
                .orElseThrow(() -> new RuntimeException("Estudiante no encontrado con matrícula: " + matricula));
        return convertToDTO(estudiante);
    }

    @Transactional(readOnly = true)
    public List<EstudianteDTO> getEstudiantesByCurso(Integer cursoId) {
        return estudianteRepository.findByCursoId(cursoId)
                .stream()
                .map(this::convertToDTO)
                .collect(Collectors.toList());
    }

    @Transactional(readOnly = true)
    public List<EstudianteDTO> getAllEstudiantes() {
        return estudianteRepository.findAll()
                .stream()
                .map(this::convertToDTO)
                .collect(Collectors.toList());
    }

    public EstudianteDTO updateEstudiante(Integer id, EstudianteDTO estudianteDTO) {
        Estudiante estudiante = estudianteRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Estudiante no encontrado con ID: " + id));

        if (!estudiante.getMatricula().equals(estudianteDTO.getMatricula()) 
                && estudianteRepository.existsByMatricula(estudianteDTO.getMatricula())) {
            throw new RuntimeException("La matrícula ya existe: " + estudianteDTO.getMatricula());
        }

        Role role = roleRepository.findById(estudianteDTO.getRolId())
                .orElseThrow(() -> new RuntimeException("Rol no encontrado con ID: " + estudianteDTO.getRolId()));

        Curso curso = cursoRepository.findById(estudianteDTO.getCursoId())
                .orElseThrow(() -> new RuntimeException("Curso no encontrado con ID: " + estudianteDTO.getCursoId()));

        estudiante.setNombre(estudianteDTO.getNombre());
        estudiante.setApellido(estudianteDTO.getApellido());
        estudiante.setEmail(estudianteDTO.getEmail());
        if (!estudianteDTO.getPassword().isEmpty()) {
            estudiante.setPassword(passwordEncoder.encode(estudianteDTO.getPassword()));
        }
        estudiante.setRole(role);
        estudiante.setCurso(curso);
        estudiante.setMatricula(estudianteDTO.getMatricula());

        Estudiante updatedEstudiante = estudianteRepository.save(estudiante);
        return convertToDTO(updatedEstudiante);
    }

    public void deleteEstudiante(Integer id) {
        if (!estudianteRepository.existsById(id)) {
            throw new RuntimeException("Estudiante no encontrado con ID: " + id);
        }
        estudianteRepository.deleteById(id);
    }

    private EstudianteDTO convertToDTO(Estudiante estudiante) {
        EstudianteDTO dto = new EstudianteDTO();
        dto.setId(estudiante.getId());
        dto.setNombre(estudiante.getNombre());
        dto.setApellido(estudiante.getApellido());
        dto.setEmail(estudiante.getEmail());
        dto.setRolId(estudiante.getRole().getId());
        dto.setCursoId(estudiante.getCurso().getId());
        dto.setMatricula(estudiante.getMatricula());
        dto.setCreatedAt(estudiante.getCreatedAt().toString());
        return dto;
    }
}

package org.smartbook.service;

import lombok.AllArgsConstructor;
import org.smartbook.dto.EvaluacionDTO;
import org.smartbook.model.Curso;
import org.smartbook.model.Evaluacion;
import org.smartbook.repository.CursoRepository;
import org.smartbook.repository.EvaluacionRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.stream.Collectors;

@Service
@AllArgsConstructor
@Transactional
public class EvaluacionService {

    private final EvaluacionRepository evaluacionRepository;
    private final CursoRepository cursoRepository;
    private static final DateTimeFormatter formatter = DateTimeFormatter.ISO_LOCAL_DATE_TIME;

    public EvaluacionDTO createEvaluacion(EvaluacionDTO evaluacionDTO) {
        Curso curso = cursoRepository.findById(evaluacionDTO.getCursoId())
                .orElseThrow(() -> new RuntimeException("Curso no encontrado con ID: " + evaluacionDTO.getCursoId()));

        Evaluacion evaluacion = new Evaluacion();
        evaluacion.setNombre(evaluacionDTO.getNombre());
        evaluacion.setDescripcion(evaluacionDTO.getDescripcion());
        evaluacion.setCurso(curso);
        evaluacion.setFecha(LocalDateTime.parse(evaluacionDTO.getFecha(), formatter));
        evaluacion.setPuntajeMaximo(evaluacionDTO.getPuntajeMaximo());
        evaluacion.setCreatedAt(LocalDateTime.now());

        Evaluacion savedEvaluacion = evaluacionRepository.save(evaluacion);
        return convertToDTO(savedEvaluacion);
    }

    @Transactional(readOnly = true)
    public EvaluacionDTO getEvaluacionById(Integer id) {
        Evaluacion evaluacion = evaluacionRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Evaluación no encontrada con ID: " + id));
        return convertToDTO(evaluacion);
    }

    @Transactional(readOnly = true)
    public List<EvaluacionDTO> getAllEvaluaciones() {
        return evaluacionRepository.findAll()
                .stream()
                .map(this::convertToDTO)
                .collect(Collectors.toList());
    }

    @Transactional(readOnly = true)
    public List<EvaluacionDTO> getEvaluacionesByCurso(Integer cursoId) {
        return evaluacionRepository.findByCursoId(cursoId)
                .stream()
                .map(this::convertToDTO)
                .collect(Collectors.toList());
    }

    public EvaluacionDTO updateEvaluacion(Integer id, EvaluacionDTO evaluacionDTO) {
        Evaluacion evaluacion = evaluacionRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Evaluación no encontrada con ID: " + id));

        Curso curso = cursoRepository.findById(evaluacionDTO.getCursoId())
                .orElseThrow(() -> new RuntimeException("Curso no encontrado con ID: " + evaluacionDTO.getCursoId()));

        evaluacion.setNombre(evaluacionDTO.getNombre());
        evaluacion.setDescripcion(evaluacionDTO.getDescripcion());
        evaluacion.setCurso(curso);
        evaluacion.setFecha(LocalDateTime.parse(evaluacionDTO.getFecha(), formatter));
        evaluacion.setPuntajeMaximo(evaluacionDTO.getPuntajeMaximo());

        Evaluacion updatedEvaluacion = evaluacionRepository.save(evaluacion);
        return convertToDTO(updatedEvaluacion);
    }

    public void deleteEvaluacion(Integer id) {
        if (!evaluacionRepository.existsById(id)) {
            throw new RuntimeException("Evaluación no encontrada con ID: " + id);
        }
        evaluacionRepository.deleteById(id);
    }

    private EvaluacionDTO convertToDTO(Evaluacion evaluacion) {
        EvaluacionDTO dto = new EvaluacionDTO();
        dto.setId(evaluacion.getId());
        dto.setNombre(evaluacion.getNombre());
        dto.setDescripcion(evaluacion.getDescripcion());
        dto.setCursoId(evaluacion.getCurso().getId());
        dto.setFecha(evaluacion.getFecha().format(formatter));
        dto.setPuntajeMaximo(evaluacion.getPuntajeMaximo());
        dto.setCreatedAt(evaluacion.getCreatedAt().format(formatter));
        return dto;
    }
}

package org.smartbook.service;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.stereotype.Service;

import java.util.Date;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Function;

@Service
public class JwtService {

    @Value("${jwt.secret:MiClaveSecretaMuyLargaParaQueSeaSeguraYNoTeRompaLaAplicacionEnProducción}")
    private String jwtSecret;

    @Value("${jwt.expiration:86400000}")
    private long jwtExpiration;

    public String generateToken(UserDetails userDetails) {
        Map<String, Object> claims = new HashMap<>();
        return createToken(claims, userDetails.getUsername());
    }

    public String generateToken(String email) {
        Map<String, Object> claims = new HashMap<>();
        return createToken(claims, email);
    }

    private String createToken(Map<String, Object> claims, String subject) {
        return Jwts.builder()
                .setClaims(claims)
                .setSubject(subject)
                .setIssuedAt(new Date())
                .setExpiration(new Date(System.currentTimeMillis() + jwtExpiration))
                .signWith(Keys.hmacShaKeyFor(jwtSecret.getBytes()), SignatureAlgorithm.HS256)
                .compact();
    }

    public String extractEmail(String token) {
        return extractClaim(token, Claims::getSubject);
    }

    public Date extractExpiration(String token) {
        return extractClaim(token, Claims::getExpiration);
    }

    private <T> T extractClaim(String token, Function<Claims, T> claimsResolver) {
        final Claims claims = extractAllClaims(token);
        return claimsResolver.apply(claims);
    }

    private Claims extractAllClaims(String token) {
        return Jwts.parserBuilder()
                .setSigningKey(Keys.hmacShaKeyFor(jwtSecret.getBytes()))
                .build()
                .parseClaimsJws(token)
                .getBody();
    }

    private Boolean isTokenExpired(String token) {
        return extractExpiration(token).before(new Date());
    }

    public Boolean validateToken(String token, UserDetails userDetails) {
        final String email = extractEmail(token);
        return (email.equals(userDetails.getUsername())) && !isTokenExpired(token);
    }

    public Boolean validateToken(String token, String email) {
        final String tokenEmail = extractEmail(token);
        return tokenEmail.equals(email) && !isTokenExpired(token);
    }
}

package org.smartbook.service;

import lombok.AllArgsConstructor;
import org.smartbook.dto.NotaDTO;
import org.smartbook.model.Evaluacion;
import org.smartbook.model.Estudiante;
import org.smartbook.model.Nota;
import org.smartbook.repository.EvaluacionRepository;
import org.smartbook.repository.EstudianteRepository;
import org.smartbook.repository.NotaRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.stream.Collectors;

@Service
@AllArgsConstructor
@Transactional
public class NotaService {

    private final NotaRepository notaRepository;
    private final EstudianteRepository estudianteRepository;
    private final EvaluacionRepository evaluacionRepository;

    public NotaDTO createNota(NotaDTO notaDTO) {
        Estudiante estudiante = estudianteRepository.findById(notaDTO.getEstudianteId())
                .orElseThrow(() -> new RuntimeException("Estudiante no encontrado con ID: " + notaDTO.getEstudianteId()));

        Evaluacion evaluacion = evaluacionRepository.findById(notaDTO.getEvaluacionId())
                .orElseThrow(() -> new RuntimeException("Evaluación no encontrada con ID: " + notaDTO.getEvaluacionId()));

        Nota nota = new Nota();
        nota.setEstudiante(estudiante);
        nota.setEvaluacion(evaluacion);
        nota.setNota(notaDTO.getNota());

        Nota savedNota = notaRepository.save(nota);
        return convertToDTO(savedNota);
    }

    @Transactional(readOnly = true)
    public NotaDTO getNotaById(Integer id) {
        Nota nota = notaRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Nota no encontrada con ID: " + id));
        return convertToDTO(nota);
    }

    @Transactional(readOnly = true)
    public List<NotaDTO> getAllNotas() {
        return notaRepository.findAll()
                .stream()
                .map(this::convertToDTO)
                .collect(Collectors.toList());
    }

    @Transactional(readOnly = true)
    public List<NotaDTO> getNotasByEstudiante(Integer estudianteId) {
        return notaRepository.findByEstudianteId(estudianteId)
                .stream()
                .map(this::convertToDTO)
                .collect(Collectors.toList());
    }

    @Transactional(readOnly = true)
    public List<NotaDTO> getNotasByEvaluacion(Integer evaluacionId) {
        return notaRepository.findByEvaluacionId(evaluacionId)
                .stream()
                .map(this::convertToDTO)
                .collect(Collectors.toList());
    }

    public NotaDTO updateNota(Integer id, NotaDTO notaDTO) {
        Nota nota = notaRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Nota no encontrada con ID: " + id));

        Estudiante estudiante = estudianteRepository.findById(notaDTO.getEstudianteId())
                .orElseThrow(() -> new RuntimeException("Estudiante no encontrado con ID: " + notaDTO.getEstudianteId()));

        Evaluacion evaluacion = evaluacionRepository.findById(notaDTO.getEvaluacionId())
                .orElseThrow(() -> new RuntimeException("Evaluación no encontrada con ID: " + notaDTO.getEvaluacionId()));

        nota.setEstudiante(estudiante);
        nota.setEvaluacion(evaluacion);
        nota.setNota(notaDTO.getNota());

        Nota updatedNota = notaRepository.save(nota);
        return convertToDTO(updatedNota);
    }

    public void deleteNota(Integer id) {
        if (!notaRepository.existsById(id)) {
            throw new RuntimeException("Nota no encontrada con ID: " + id);
        }
        notaRepository.deleteById(id);
    }

    private NotaDTO convertToDTO(Nota nota) {
        return new NotaDTO(
                nota.getId(),
                nota.getEstudiante().getId(),
                nota.getEvaluacion().getId(),
                nota.getNota()
        );
    }
}

